<?php
/**
 * R5.later-perf-a/b parity harness — runs in its own PHP process (one Bricks
 * version per process; the Bricks class names are fixed), without WordPress.
 *
 *   php parity-harness.php <bricks> [<adopt-fingerprint>]
 *
 * <bricks> is either a fixture file generated by extract.php or a real
 * `themes/bricks` directory (read-only). <adopt-fingerprint> forces
 * IndexedAcfProvider to run another version's vendored register_tag() — used
 * to prove the comparison catches a wrong copy.
 *
 * Prints one JSON object; VisualEditorBricksAcfTagIndexParityTest asserts on it.
 */

if (PHP_SAPI !== 'cli') {
    exit(1);
}

// ---------------------------------------------------------------------------
// Minimal WordPress stand-ins (hooks + options) — just what the shim touches.
// ---------------------------------------------------------------------------

$GLOBALS['dbvc_harness_hooks'] = [];
$GLOBALS['dbvc_harness_options'] = [];
$GLOBALS['dbvc_harness_warnings'] = [];

define('ABSPATH', '/dbvc-parity-harness/');

function add_filter($hook, $callback, $priority = 10, $args = 1)
{
    $GLOBALS['dbvc_harness_hooks'][$hook][$priority][] = $callback;
    return true;
}

function add_action($hook, $callback, $priority = 10, $args = 1)
{
    return add_filter($hook, $callback, $priority, $args);
}

function has_filter($hook, $callback = false)
{
    foreach ($GLOBALS['dbvc_harness_hooks'][$hook] ?? [] as $priority => $callbacks) {
        foreach ($callbacks as $registered) {
            if ($callback === false || $registered === $callback) {
                return $callback === false ? true : $priority;
            }
        }
    }

    return false;
}

function has_action($hook, $callback = false)
{
    return has_filter($hook, $callback);
}

function remove_filter($hook, $callback, $priority = 10)
{
    foreach ($GLOBALS['dbvc_harness_hooks'][$hook][$priority] ?? [] as $i => $registered) {
        if ($registered === $callback) {
            unset($GLOBALS['dbvc_harness_hooks'][$hook][$priority][$i]);
            return true;
        }
    }

    return false;
}

function remove_action($hook, $callback, $priority = 10)
{
    return remove_filter($hook, $callback, $priority);
}

function apply_filters($hook, $value, ...$args)
{
    return $value;
}

function get_option($name, $default = false)
{
    return array_key_exists($name, $GLOBALS['dbvc_harness_options']) ? $GLOBALS['dbvc_harness_options'][$name] : $default;
}

function update_option($name, $value)
{
    $GLOBALS['dbvc_harness_options'][$name] = $value;
    return true;
}

set_error_handler(static function ($severity, $message, $file, $line) {
    $GLOBALS['dbvc_harness_warnings'][] = basename((string) $file) . ':' . $line . ' ' . $message;
    return true;
});

// ---------------------------------------------------------------------------
// Load Bricks (fixture or real theme) and the DBVC classes.
// ---------------------------------------------------------------------------

$bricks = $argv[1] ?? '';
$adopt_override = isset($argv[2]) && $argv[2] !== '' ? $argv[2] : null;
// 'noskip': force the indexed lookup NOT to skip is_loop_outer tags (sensitivity check).
$force_no_skip = ($argv[3] ?? '') === 'noskip';
$fixture_mode = is_file($bricks);
$GLOBALS['dbvc_harness_force_no_skip'] = $force_no_skip;

if ($fixture_mode) {
    require $bricks;
} elseif (is_dir($bricks . '/includes/integrations/dynamic-data')) {
    $dir = $bricks . '/includes/integrations/dynamic-data';
    foreach (['providers/provider-interface.php', 'providers/base.php', 'providers/provider-acf.php', 'providers.php'] as $file) {
        require $dir . '/' . $file;
    }
} else {
    fwrite(STDERR, "no Bricks at {$bricks}\n");
    exit(2);
}

$src = dirname(__DIR__, 3) . '/addons/visual-editor/src/Performance/Bricks';
require $src . '/AcfTagIndex.php';
require $src . '/ProviderFingerprint.php';
require $src . '/IndexedAcfProvider.php';
require $src . '/AcfTagIndexShim.php';

use Bricks\Integrations\Dynamic_Data\Providers;
use Bricks\Integrations\Dynamic_Data\Providers\Provider_Acf;
use Dbvc\VisualEditor\Performance\Bricks\AcfTagIndexShim;
use Dbvc\VisualEditor\Performance\Bricks\IndexedAcfProvider;
use Dbvc\VisualEditor\Performance\Bricks\ProviderFingerprint;

// ---------------------------------------------------------------------------
// ACF schemas: one hand-written schema that reaches every branch of
// register_tag(), plus seeded random schemas with heavy name/key reuse.
// ---------------------------------------------------------------------------

function dbvc_harness_field($key, $name, $label, $type, array $extra = [])
{
    return array_merge(['key' => $key, 'name' => $name, 'label' => $label, 'type' => $type], $extra);
}

