        // Duplicate name in another "field group" → 'duplicate' flag.
        $f('field_t_text_dup', 'headline', 'Headline (other group)', 'text'),

        // Three-deep nested groups (the indexed lookup path), with locations.
        $f('field_g_hero', 'hero_section', 'Hero section', 'group', ['_bricks_locations' => ['post_type:page', 'options'], 'sub_fields' => [
            $f('field_g_hero_h1', 'hero_h1', 'Hero H1', 'wysiwyg'),
            $f('field_g_hero_cta', 'hero_cta', 'Hero CTA', 'group', ['sub_fields' => [
