        $f('field_g_office', 'office', 'Office', 'group', ['sub_fields' => $address]),

        // Repeater with a group inside, and a repeater inside the repeater.
        $f('field_r_team', 'team', 'Team', 'repeater', ['_bricks_locations' => ['post_type:page'], 'sub_fields' => [
            $f('field_r_team_name', 'name', 'Name', 'text'),
            $f('field_r_team_photo', 'photo', 'Photo', 'image'),
            $f('field_r_team_social', 'social', 'Social', 'group', ['sub_fields' => [
