            $f('field_r_team_skills', 'skills', 'Skills', 'repeater', ['sub_fields' => [
                $f('field_r_team_skill', 'skill', 'Skill', 'text'),
            ]]),
        ]]),

        // Flexible content: layouts keyed by layout key, one whose key != name,
        // and a parent_layout that matches no layout (falls back to the key).
        $f('field_fc_blocks', 'blocks', 'Blocks', 'flexible_content', ['layouts' => [
            'layout_hero' => ['key' => 'layout_hero', 'name' => 'hero', 'label' => 'Hero', 'sub_fields' => [
                $f('field_fc_hero_title', 'title', 'Title', 'text', ['parent_layout' => 'layout_hero']),
                $f('field_fc_hero_img', 'image', 'Image', 'image', ['parent_layout' => 'layout_hero']),
