        $f('field_c_cta', 'cta_clone', 'CTA clone', 'clone', ['display' => 'group', '_bricks_locations' => ['post_type:post'], 'sub_fields' => [
            $f('field_t_link', 'cta_clone_cta_link', 'CTA link', 'link', ['_bricks_locations' => ['post_type:page', 'post_type:post']]),
            $f('field_t_text', 'cta_clone_headline', 'Headline', 'text'),
