            ]]),
        ]]),
        $f('field_c_nolabel', 'bare_clone', '', 'clone', ['display' => 'group', 'sub_fields' => [
            $f('field_t_tf', 'bare_clone_featured', 'Featured', 'true_false'),
        ]]),
        $f('field_c_seamless', 'seamless_clone', 'Seamless', 'clone', ['display' => 'seamless', 'sub_fields' => [
            $f('field_t_text', 'headline', 'Headline', 'text'),
        ]]),
        $f('field_c_empty', 'empty_clone', 'Empty', 'clone', ['display' => 'group', 'sub_fields' => []]),
        // A group-display clone nested inside a group (parent_field passes through).
        $f('field_g_wrap', 'wrapper', 'Wrapper', 'group', ['sub_fields' => [
            $f('field_c_inner', 'inner_clone', 'Inner clone', 'clone', ['display' => 'group', 'sub_fields' => [
                $f('field_addr_city', 'inner_clone_city', 'City', 'text'),
            ]]),
        ]]),
    ];
}

function dbvc_harness_random_schema($seed, $count)
{
    mt_srand($seed);
    $types = ['text', 'textarea', 'number', 'email', 'url', 'image', 'file', 'wysiwyg', 'select', 'link', 'post_object', 'relationship', 'true_false', 'message', 'group', 'group', 'group', 'repeater', 'flexible_content', 'clone'];
    $names = [];
    for ($i = 0; $i < 25; $i++) {
        $names[] = 'n' . $i;
    }

    // Keys are reused heavily (as ACF clones do) so the "first tag in array
    // order" semantics of the nested-group lookup are exercised, but container
    // keys are drawn per depth: real ACF schemas have no key cycles, and a
    // cycle would send stock Bricks' recursive lookup into unbounded recursion.
    $make = static function ($depth, $layout = null) use (&$make, $types, $names) {
        $type = $types[mt_rand(0, count($types) - 1)];
        if ($depth >= 4 && in_array($type, ['group', 'repeater', 'flexible_content', 'clone'], true)) {
            $type = 'text';
        }
        $container = in_array($type, ['group', 'repeater', 'flexible_content', 'clone'], true);
        $key = $container ? 'field_c' . $depth . '_' . mt_rand(0, 6) : 'field_l' . mt_rand(0, 40);
        $field = dbvc_harness_field($key, $names[mt_rand(0, count($names) - 1)], 'L' . mt_rand(0, 99), $type);
        if ($layout !== null) {
            $field['parent_layout'] = $layout;
        }
        if (mt_rand(0, 3) === 0) {
            $field['_bricks_locations'] = ['loc' . mt_rand(0, 3)];
        }
        if (in_array($type, ['group', 'repeater', 'clone'], true)) {
            $field['sub_fields'] = [];
            $n = mt_rand(0, 4);
            for ($i = 0; $i < $n; $i++) {
                // Clone sub-fields are registered against the clone's parent, so
                // inside a flexible layout they carry that layout like any sub-field.
                $field['sub_fields'][] = $make($depth + 1, $type === 'clone' ? $layout : null);
            }
        }
        if ($type === 'clone') {
            $field['display'] = mt_rand(0, 2) ? 'group' : 'seamless';
            if (mt_rand(0, 4) === 0) {
                $field['label'] = '';
            }
        }
        if ($type === 'flexible_content') {
            $field['layouts'] = [];
            $n = mt_rand(1, 3);
            for ($l = 0; $l < $n; $l++) {
                $lk = 'layout_' . mt_rand(0, 5);
                $layout_def = ['key' => $lk, 'name' => 'lay' . mt_rand(0, 5), 'label' => 'Layout ' . $l, 'sub_fields' => []];
                $m = mt_rand(1, 3);
                for ($i = 0; $i < $m; $i++) {
                    $layout_def['sub_fields'][] = $make($depth + 1, mt_rand(0, 5) ? $lk : 'layout_none');
                }
                if (mt_rand(0, 1)) {
                    $field['layouts'][$lk] = $layout_def;
                } else {
                    $field['layouts'][] = $layout_def;
                }
            }
        }

        return $field;
    };

    $schema = [];
    for ($i = 0; $i < $count; $i++) {
        $schema[] = $make(0);
    }

    return $schema;
}

// ---------------------------------------------------------------------------
// Comparisons.
// ---------------------------------------------------------------------------

function dbvc_harness_stock()
{
    $stock = new Provider_Acf('acf');
    foreach ([['bricks/setup/control_options', 'add_control_options'], ['bricks/query/run', 'set_loop_query'], ['bricks/query/loop_object', 'set_loop_object']] as [$hook, $method]) {
        remove_filter($hook, [$stock, $method], 10);
    }

    return $stock;
}

function dbvc_harness_fast($fingerprint)
{
    $fast = (new ReflectionClass(IndexedAcfProvider::class))->newInstanceWithoutConstructor();
    $fast->adopt('acf', $fingerprint);

    if (! empty($GLOBALS['dbvc_harness_force_no_skip'])) {
        $skip = new ReflectionProperty(IndexedAcfProvider::class, 'skipLoopOuter');
        $skip->setAccessible(true);
        $skip->setValue($fast, false);
    }

    return $fast;
}

function dbvc_harness_compare(array $schema, $fingerprint)
{
    $stock = dbvc_harness_stock();
    $fast = dbvc_harness_fast($fingerprint);
    $warnings_before = count($GLOBALS['dbvc_harness_warnings']);

    foreach ($schema as $field) {
        $stock->register_tag($field);
    }
    $stock_warnings = count($GLOBALS['dbvc_harness_warnings']) - $warnings_before;

    foreach ($schema as $field) {
        $fast->register_tag($field);
    }

    $differing = [];
    foreach (array_unique(array_merge(array_keys($stock->tags), array_keys($fast->tags))) as $name) {
        if (! array_key_exists($name, $stock->tags) || ! array_key_exists($name, $fast->tags) || $stock->tags[$name] !== $fast->tags[$name]) {
            $differing[] = 'tags:' . $name;
        }
    }
    foreach (array_unique(array_merge(array_keys($stock->loop_tags), array_keys($fast->loop_tags))) as $name) {
        if (! array_key_exists($name, $stock->loop_tags) || ! array_key_exists($name, $fast->loop_tags) || $stock->loop_tags[$name] !== $fast->loop_tags[$name]) {
            $differing[] = 'loop_tags:' . $name;
        }
    }

    $count = static function (array $tags, $key) {
        return count(array_filter($tags, static function ($tag) use ($key) {
            return ! empty($tag[$key]);
        }));
    };

    return [
        'identical' => $stock->tags === $fast->tags && $stock->loop_tags === $fast->loop_tags,
        'orderIdentical' => array_keys($stock->tags) === array_keys($fast->tags) && array_keys($stock->loop_tags) === array_keys($fast->loop_tags),
        'tags' => count($stock->tags),
        'loopTags' => count($stock->loop_tags),
        'nestedGroupTags' => $count($stock->tags, 'nested_group'),
        'duplicateTags' => $count($stock->tags, 'duplicate'),
        'loopOuterTags' => $count($stock->tags, 'is_loop_outer'),
        'cloneLabelledTags' => count(array_filter($stock->tags, static function ($tag) {
            return strpos((string) ($tag['label'] ?? ''), '(CTA clone)') !== false;
        })),
        'differing' => array_slice($differing, 0, 20),
        'differingCount' => count($differing),
        'stockWarnings' => $stock_warnings,
    ];
}

/**
 * Vendored copy → Bricks source, undoing exactly the documented edits.
 */
function dbvc_harness_unvendor($normalized)
{
    $lines = [];
    foreach (explode("\n", $normalized) as $line) {
        if (strpos($line, '// R5.later-perf-a') !== false) {
            continue;
        }
        $lines[] = $line;
    }
    $source = implode("\n", $lines);
    $source = preg_replace('/^private function register_tag_bricks_[0-9_]+\(/', 'public function register_tag(', $source, 1, $signature);
    $source = str_replace("\$this->callParentPrivate( 'get_fields_by_context', null )", 'self::get_fields_by_context()', $source, $contexts);
    $source = str_replace("\$this->callParentPrivate( 'get_flexible_content_parent_layout_data', \$this, ", '$this->get_flexible_content_parent_layout_data( ', $source, $layouts);

    return [$source, ['signature' => $signature, 'contexts' => $contexts, 'layouts' => $layouts, 'indexLines' => count(explode("\n", $normalized)) - count($lines)]];
}

// ---------------------------------------------------------------------------
// Run.
// ---------------------------------------------------------------------------

$out = [
    'fixtureMode' => $fixture_mode,
    'fingerprint' => ProviderFingerprint::current(),
    'fieldsCacheFingerprint' => ProviderFingerprint::fieldsCacheCurrent(),
];
$fingerprint = $out['fingerprint'];
$out['known'] = ProviderFingerprint::isKnown($fingerprint);
$out['fieldsCacheKnown'] = ProviderFingerprint::isKnownFieldsCache($out['fieldsCacheFingerprint']);
$out['label'] = ProviderFingerprint::label($fingerprint);
$out['variant'] = ProviderFingerprint::registerTagVariant($fingerprint);
$out['registryAccessible'] = ProviderFingerprint::providersRegistryAccessible();

// The gate and verify() on an untouched site.
$out['gateBeforeVerify'] = AcfTagIndexShim::gate();
update_option(AcfTagIndexShim::OPTION_ENABLED, '1');
AcfTagIndexShim::arm();
$out['armStateBeforeVerify'] = AcfTagIndexShim::state();
$out['swapHookedBeforeVerify'] = has_action('init', [AcfTagIndexShim::class, 'swap']);
AcfTagIndexShim::reset();

if (! $out['known'] && $adopt_override === null) {
    $verify = AcfTagIndexShim::verify(true);
    $out['verify'] = ['ok' => $verify['ok'], 'reason' => $verify['reason']];
    $out['verifiedOption'] = get_option(AcfTagIndexShim::OPTION_VERIFIED, '');
    try {
        dbvc_harness_fast($fingerprint);
        $out['adoptUnknown'] = 'accepted';
    } catch (LogicException $e) {
        $out['adoptUnknown'] = 'refused';
    }
    $out['warnings'] = $GLOBALS['dbvc_harness_warnings'];
    echo json_encode($out);
    exit(0);
}

$adopt = $adopt_override ?? $fingerprint;

// Textual check of the vendored copy against this Bricks' register_tag().
$variant = ProviderFingerprint::registerTagVariant($adopt);
[$unvendored, $edits] = dbvc_harness_unvendor((string) ProviderFingerprint::methodSource(IndexedAcfProvider::class, (string) $variant));
$out['source'] = [
    'stock' => ProviderFingerprint::methodSource(ProviderFingerprint::PROVIDER_ACF_CLASS, 'register_tag'),
    'vendored' => $unvendored,
    'edits' => $edits,
];

// Tag-by-tag parity.
$out['parity'] = ['handwritten' => dbvc_harness_compare(dbvc_harness_handwritten_schema(), $adopt)];
foreach ([20261112, 7, 13, 2313, 238] as $seed) {
    $out['parity']['random:' . $seed] = dbvc_harness_compare(dbvc_harness_random_schema($seed, 120), $adopt);
}

if ($fixture_mode && $adopt_override === null && ! $force_no_skip) {
    // verify() end to end (the fixture's register_tags() replays the schema).
    Provider_Acf::$fixture_fields = array_merge(dbvc_harness_handwritten_schema(), dbvc_harness_random_schema(99, 150));
    $verify = AcfTagIndexShim::verify(true);
    $out['verify'] = ['ok' => $verify['ok'], 'reason' => $verify['reason'], 'tags' => $verify['tags'], 'loopTags' => $verify['loopTags'], 'differing' => $verify['differing']];
    $out['verifiedOption'] = get_option(AcfTagIndexShim::OPTION_VERIFIED, '');
    $out['gateAfterVerify'] = AcfTagIndexShim::gate();

    // arm → swap exactly as at runtime, then compare the swapped provider's registry.
    $reflection = new ReflectionProperty(Providers::class, 'providers');
    $reflection->setAccessible(true);
    $registered_stock = new Provider_Acf('acf');
    $reflection->setValue(null, ['acf' => $registered_stock]);

    AcfTagIndexShim::arm();
    $out['armState'] = AcfTagIndexShim::state();
    $out['swapHooked'] = has_action('init', [AcfTagIndexShim::class, 'swap']);
    AcfTagIndexShim::swap();
    $out['swapState'] = AcfTagIndexShim::state();

    $swapped = $reflection->getValue()['acf'];
    $out['swappedIsIndexed'] = $swapped instanceof IndexedAcfProvider;
    $out['filtersRepointed'] = [];
    foreach ([['bricks/setup/control_options', 'add_control_options'], ['bricks/query/run', 'set_loop_query'], ['bricks/query/loop_object', 'set_loop_object']] as [$hook, $method]) {
        $out['filtersRepointed'][] = has_filter($hook, [$swapped, $method]) === 10 && has_filter($hook, [$registered_stock, $method]) === false;
    }
    $swapped->register_tags();
    $reference = dbvc_harness_stock();
    $reference->register_tags();
    $out['swappedIdentical'] = $swapped->tags === $reference->tags && $swapped->loop_tags === $reference->loop_tags;
    $out['swappedTags'] = count($swapped->tags);

    // A verified marker for another fingerprint does not count.
    update_option(AcfTagIndexShim::OPTION_VERIFIED, 'failed:' . $fingerprint);
    $out['gateAfterFailedMarker'] = AcfTagIndexShim::gate();
}

$out['warnings'] = $GLOBALS['dbvc_harness_warnings'];
echo json_encode($out);
